css:
/* =========================================================
   PDF Extractor — Light UI (fond blanc)
   ========================================================= */

/* ---------- Design tokens ---------- */
:root{
  --fx-bg:#f9fafb;                 /* fond global blanc/gris clair */
  --fx-surface:#ffffff;            /* surface carte */
  --fx-surface-2:#f3f4f6;
  --fx-card:#ffffff;
  --fx-text:#111827;               /* texte principal */
  --fx-text-dim:#374151;
  --fx-muted:#6b7280;
  --fx-line:#e5e7eb;

  --fx-primary:#4f46e5;            /* indigo */
  --fx-primary-2:#8b5cf6;          /* violet */
  --fx-accent:#0ea5e9;             /* bleu clair */
  --fx-success:#10b981;            /* vert */
  --fx-warning:#f59e0b;            /* amber */
  --fx-danger:#ef4444;             /* rouge */

  --fx-shadow:0 8px 24px rgba(0,0,0,.06);
  --fx-soft:0 4px 12px rgba(0,0,0,.05);

  --fx-radius-xl:18px;
  --fx-radius:14px;
  --fx-radius-sm:10px;

  --fx-gradient:linear-gradient(135deg, var(--fx-primary) 0%, var(--fx-primary-2) 50%, var(--fx-accent) 100%);
}

/* ---------- Page backdrop ---------- */
body{
  background:var(--fx-bg);
  color:var(--fx-text);
  font-family: system-ui, sans-serif;
}

/* ---------- Container (grosse carte) ---------- */
.pdf-extractor-container{
  background:var(--fx-card);
  border:1px solid var(--fx-line);
  border-radius:var(--fx-radius-xl);
  box-shadow:var(--fx-shadow);
  padding:28px;
  max-width:1100px;
  margin:28px auto;
  color:var(--fx-text);
}

/* Ruban dégradé en haut de la carte */
.pdf-extractor-container::before{
  content:"";
  position:absolute; inset:auto 18px 100% 18px; height:4px;
  background:var(--fx-gradient);
  border-radius:10px 10px 0 0;
}

/* ---------- Titres & textes ---------- */
.pdf-extractor-container h3{
  font-weight:800; letter-spacing:.2px;
  background:var(--fx-gradient);
  -webkit-background-clip:text; background-clip:text; color:transparent;
  margin-bottom:6px;
}
.pdf-extractor-container p{ color:var(--fx-muted); margin-bottom:18px; }

/* ---------- Cartes secondaires (upload, panels, résultats) ---------- */
.upload-section,
#target-fields-panel,
#results-section,
#document-info{
  background:var(--fx-surface);
  border:1px solid var(--fx-line);
  border-radius:var(--fx-radius);
  box-shadow:var(--fx-soft);
}

.upload-section{ padding:20px; transition:border-color .25s ease, transform .05s ease; }
.upload-section:hover{ border-color:var(--fx-primary); transform:translateY(-1px); }

/* ---------- Inputs & boutons ---------- */
#pdf-files,
#target-doctype{
  background:var(--fx-surface-2);
  color:var(--fx-text);
  border:1px solid var(--fx-line);
  border-radius:var(--fx-radius-sm);
  padding:10px 12px;
}
#pdf-files:focus,#target-doctype:focus{
  outline:none;
  box-shadow:0 0 0 3px rgba(79,70,229,.25);
  border-color:var(--fx-primary);
}

#extract-btn{
  background:var(--fx-gradient);
  border:none; color:#fff;
  padding:10px 18px; border-radius:14px; font-weight:700;
  box-shadow:0 4px 12px rgba(79,70,229,.25);
  transition:transform .05s ease, opacity .2s ease;
}
#extract-btn:hover{ opacity:.96; }
#extract-btn:active{ transform:translateY(1px); }

#load-fields-btn{
  background:#f3f4f6;
  border:1px solid var(--fx-line); color:#111827; font-weight:600;
  border-radius:14px;
}
#load-fields-btn:hover{ border-color:var(--fx-primary); color:var(--fx-primary); }

/* ---------- Indicateurs document ---------- */
#document-info .alert{
  background:#eef2ff;
  border:1px solid #c7d2fe;
  color:#1e3a8a; border-radius:12px;
}

/* ---------- Onglets ---------- */
#pdf-tabs{ border-bottom:1px solid var(--fx-line); }
#pdf-tabs .nav-link{
  color:var(--fx-muted);
  background:transparent;
  border:1px solid transparent;
  border-top-left-radius:12px; border-top-right-radius:12px;
  margin-right:6px; padding:8px 14px;
  transition:all .2s ease;
}
#pdf-tabs .nav-link:hover{
  color:var(--fx-primary);
  background:#f9fafb;
  border-color:var(--fx-line);
}
#pdf-tabs .nav-link.active{
  color:var(--fx-text);
  background:#fff;
  border-color:var(--fx-line) var(--fx-line) transparent;
}

/* ---------- Tableau des extractions ---------- */
#extraction-table{
  background:#fff;
  border:1px solid var(--fx-line) !important;
  border-radius:var(--fx-radius);
  overflow:hidden; box-shadow:var(--fx-soft);
  color:var(--fx-text);
}
#extraction-table thead th{
  background:#f3f4f6;
  color:#374151; border-bottom:1px solid var(--fx-line);
  text-transform:uppercase; letter-spacing:.4px; font-weight:700;
}
#extraction-table tbody tr:hover{ background:#f9fafb; }

/* Colonne catégorie */
#extraction-table tbody td:first-child{ font-weight:600; color:#111827; }

/* Clé technique */
#extraction-table code{
  background:#f3f4f6;
  color:#374151; border-radius:8px; padding:2px 6px;
}

/* Aperçu valeur */
.value-preview{
  display:inline-block; max-width:560px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  text-decoration:underline dotted #9ca3af;
  color:#111827;
}

/* Boutons ligne */
#extraction-table .btn{ border-radius:10px; font-weight:600; }
#extraction-table .btn-outline-info:hover{
  color:#0284c7; border-color:#bae6fd; background:#e0f2fe;
}
#extraction-table .btn-outline-danger:hover{
  color:#dc2626; border-color:#fecaca; background:#fee2e2;
}

/* ---------- Barre actions ---------- */
#save-btn{ background:var(--fx-success); border-color:var(--fx-success); color:#fff; }
#export-btn{ background:var(--fx-accent); border-color:var(--fx-accent); color:#fff; }
#create-doctype-btn{ background:var(--fx-warning); border-color:var(--fx-warning); color:#111; }

/* ---------- Responsive ---------- */
@media (max-width: 992px){
  .pdf-extractor-container{ margin:16px; padding:20px; }
  #pdf-files{ display:block; margin:0 0 10px 0; width:100%; }
  #extract-btn{ width:100%; }
  .value-preview{ max-width:100%; }
}
@media (max-width: 576px){
  .pdf-extractor-container{ padding:16px; }
  #results-section .btn{ width:100%; margin:6px 0 !important; }
}
/* Bouton Charger les champs */
#load-fields-btn {
  min-width: 220px;     /* bouton plus large */
  padding: 12px 20px;   /* padding interne */
  font-size: 15px;
}
#target-doctype {
  background-color: #ffffff !important;   /* fond blanc */
  color: #111827 !important;              /* texte foncé */
  border: 1px solid #d1d5db !important;
  border-radius: 10px;
  padding: 12px 14px;                     /* <-- augmente la taille interne */
  font-size: 15px;                        /* texte un peu plus grand */
  height: auto;                           /* laisse le padding gérer la hauteur */
  line-height: 1.4;                       /* espace vertical confortable */
}

#target-doctype option {
  background-color: #ffffff;
  color: #111827;
  padding: 8px 12px;                      /* options aussi plus aérées */
}

javascript:
let currentExtraction = null;
let targetFields = [];      // champs du doctype sélectionné
let selectedDoctype = "";   // doctype choisi

$(document).ready(function () {
  $('#extract-btn').click(function () {
    const input = document.getElementById('pdf-files');
    if (!input.files.length) {
      frappe.msgprint('Veuillez sélectionner au moins un PDF (max 10).');
      return;
    }
    if (input.files.length > 10) {
      frappe.msgprint('Vous pouvez télécharger au maximum 10 fichiers.');
      return;
    }
    extractManyPDFs(Array.from(input.files));
  });

  $('#save-btn').click(function () {
    saveTableData();
  });

  $('#export-btn').click(function () {
    exportData();
  });

  // 1) Charger la liste des doctypes au chargement de la page
  frappe.call({
    method: 'company_creation.pdf_extractor.api.get_available_doctypes',
    callback: function (r) {
      if (r.message && r.message.success) {
        const sel = $('#target-doctype');
        (r.message.doctypes || []).forEach(dt => {
          sel.append(`<option value="${frappe.utils.escape_html(dt)}">${frappe.utils.escape_html(dt)}</option>`);
        });
        // pré-sélection optionnelle
        if ((r.message.doctypes || []).includes('CompanyCreationRequest')) {
          sel.val('CompanyCreationRequest');
        }
      }
    }
  });

  // 2) Bouton "Charger les champs"
  $('#load-fields-btn').click(function () {
    selectedDoctype = $('#target-doctype').val();
    if (!selectedDoctype) {
      frappe.msgprint('Choisissez un Doctype.');
      return;
    }
    frappe.call({
      method: 'company_creation.pdf_extractor.api.get_doctype_fields',
      args: { doctype: selectedDoctype },
      callback: function (r) {
        if (r.message && r.message.success) {
          targetFields = r.message.fields || [];
          renderTargetFields(targetFields);
          $('#target-fields-panel').show();
        } else {
          frappe.msgprint('Erreur: ' + ((r.message && r.message.error) || 'chargement des champs'));
        }
      }
    });
  });

  function renderTargetFields(fields) {
    let html = '<table class="table table-sm"><thead><tr><th>Label</th><th>Fieldname</th><th>Type</th><th>Oblig.</th></tr></thead><tbody>';
    fields.forEach(f => {
      html += `<tr>
        <td>${frappe.utils.escape_html(f.label || '')}</td>
        <td><code>${frappe.utils.escape_html(f.fieldname || '')}</code></td>
        <td>${frappe.utils.escape_html(f.fieldtype || '')}</td>
        <td>${f.reqd ? '✔️' : ''}</td>
      </tr>`;
    });
    html += '</tbody></table>';
    $('#target-fields-list').html(html);
  }
});

function extractManyPDFs(files) {
  // Doctype optionnel
  selectedDoctype = $('#target-doctype').val();
  const hasTargets = !!(selectedDoctype && targetFields && targetFields.length);

  $('#loading').show();
  $('#results-section').hide();
  $('#document-info').hide();

  const formData = new FormData();
  files.forEach((f) => formData.append('files', f, f.name));

  // on n’envoie que si on a bien des cibles
  if (hasTargets) {
    formData.append('target_doctype', selectedDoctype);
    formData.append('target_fields_json', JSON.stringify(targetFields));
  }

  window.currentFilenames = files.map(f => f.name);

  $.ajax({
    url: '/api/method/company_creation.pdf_extractor.api.upload_and_extract_any_pdf',
    type: 'POST',
    data: formData,
    processData: false,
    contentType: false,
    headers: { 'X-Frappe-CSRF-Token': frappe.csrf_token },
    success: function (response) {
      $('#loading').hide();
      const payload = response.message || response;
      if (!payload || !payload.success) {
        frappe.msgprint('Erreur: ' + (payload && payload.error ? payload.error : 'Extraction échouée'));
        return;
      }
      displayGroupedResults(payload);

      if (payload.file_errors && payload.file_errors.length) {
        const lines = payload.file_errors.map(e => `• ${e.filename}: ${e.error}`).join('<br>');
        frappe.msgprint({ title: 'Certains fichiers ont échoué', message: lines, wide: true });
      }
    },
    error: function (xhr, status, error) {
      $('#loading').hide();
      frappe.msgprint('Erreur de communication: ' + error);
    }
  });
}

function displayUniversalResults(data, targetSelector = '#data-table') {
  $('#doc-type').text(data.document_type || 'Document');
  $('#confidence').text(Math.round((data.confidence || 0) * 100));
  $('#document-info').show();

  // Stocker pour Save/Export/Create
  window.currentTableData = data.table_data || [];
  window.currentDocumentType = data.document_type || 'Document';

  let html = '<table class="table table-bordered" id="extraction-table">';
  html += '<thead><tr><th>Catégorie</th><th>Champ</th><th>Valeur</th><th>Actions</th></tr></thead>';
  html += '<tbody>';

  if (data.table_data && data.table_data.length) {
    data.table_data.forEach(function (row, index) {
      const shortValue = row.value && row.value.length > 50
        ? row.value.substring(0, 50) + '...' : (row.value || '');

      // ---- Champ : afficher LABEL, garder FIELDNAME caché ----
      const visibleLabel = row.label || (row.field ? row.field.replace(/_/g, ' ') : '');
      const technicalKey = row.field || '';

      html += `<tr data-index="${index}">`;
      html += '<td>' + (row.category || '') + '</td>';

      html += `<td>
        <div style="font-weight:600;">${frappe.utils.escape_html(visibleLabel)}</div>
        <div class="text-muted" style="font-size:12px;"><code>${frappe.utils.escape_html(technicalKey)}</code></div>
        <input type="hidden" class="field-name-hidden" value="${frappe.utils.escape_html(technicalKey)}">
      </td>`;

      html += `<td>
        <span class="value-preview" onclick="showFullValue(${index})" style="cursor: pointer; color: #007bff;">
          ${shortValue}
        </span>
        <input type="hidden" class="field-value" value="${(row.value || '').replace(/"/g, '&quot;')}">
      </td>`;

      html += `<td>
        <button class="btn btn-sm btn-outline-danger me-1" onclick="removeRow(${index})">🗑️</button>
        <button class="btn btn-sm btn-outline-info" onclick="editRow(${index})">✏️</button>
      </td>`;
      html += '</tr>';
    });
  }

  html += '</tbody></table>';

  $(targetSelector).html(html);
  $('#results-section').show();
}

function saveTableData() {
  if (!window.currentTableData || window.currentTableData.length === 0) {
    frappe.msgprint('Aucune donnée à sauvegarder');
    return;
  }

  // reconstruire à partir de la table affichée
  let updatedData = [];
  $('#extraction-table tbody tr').each(function (index) {
    let row = $(this);
    updatedData.push({
      category: row.find('td:first').text().trim(),
      field: row.find('.field-name-hidden').val(),                 // ⬅️ fieldname technique
      label: window.currentTableData[index]?.label || '',          // optionnel (pour info)
      value: row.find('.field-value').val() || window.currentTableData[index].value,
      type: window.currentTableData[index]?.type || 'text'
    });
  });

  frappe.call({
    method: 'company_creation.pdf_extractor.api.save_extracted_data',
    args: {
      data: updatedData,
      document_type: window.currentDocumentType || 'Document',
      filename: window.currentFilename || 'PDF'
    },
    callback: function (r) {
      if (r.message && r.message.success) {
        frappe.msgprint('✅ Données sauvegardées!');
      } else {
        frappe.msgprint('❌ Erreur: ' + (r.message ? r.message.error : 'Erreur inconnue'));
      }
    }
  });
}

function exportData() {
  let tableData = [];
  $('#extraction-table tbody tr').each(function (index) {
    let row = $(this);
    tableData.push({
      category: row.find('td:first').text().trim(),
      field: row.find('.field-name-hidden').val(),                 // ⬅️ fieldname technique
      label: window.currentTableData[index]?.label || '',
      value: row.find('.field-value').val() || window.currentTableData[index]?.value || ''
    });
  });

  let dataStr = JSON.stringify(tableData, null, 2);
  let dataUri = 'data:application/json;charset=utf-8,' + encodeURIComponent(dataStr);

  let linkElement = document.createElement('a');
  linkElement.setAttribute('href', dataUri);
  linkElement.setAttribute('download', 'extraction.json');
  linkElement.click();
}

function removeRow(index) {
  if (confirm('Supprimer ce champ ?')) {
    window.currentTableData.splice(index, 1);
    displayUniversalResults({
      table_data: window.currentTableData,
      document_type: window.currentDocumentType,
      confidence: 0.9
    });
  }
}

function editRow(index) {
  const row = window.currentTableData[index];
  const newValue = prompt('Nouvelle valeur :', row.value || '');
  if (newValue !== null) {
    window.currentTableData[index].value = newValue;
    displayUniversalResults({
      table_data: window.currentTableData,
      document_type: window.currentDocumentType,
      confidence: 0.9
    });
  }
}

function showFullValue(index) {
  const row = window.currentTableData[index];
  const title = (row.label || row.field || 'Valeur complète');
  frappe.msgprint({
    title: title,
    message: `<div style="max-height: 400px; overflow-y: auto; white-space: pre-wrap; word-wrap: break-word; padding: 10px; background: #f8f9fa; border-radius: 5px;">${row.value || ''}</div>`,
    wide: true
  });
}

function viewSavedExtractions() {
  frappe.call({
    method: 'company_creation.pdf_extractor.api.get_document_analyses',
    callback: function (r) {
      if (r.message && r.message.success) {
        if (r.message.records.length === 0) {
          frappe.msgprint('Aucune analyse sauvegardée');
          return;
        }
        showAnalysesList(r.message.records);
      } else {
        frappe.msgprint('❌ Erreur: ' + (r.message ? r.message.error : 'Erreur inconnue'));
      }
    }
  });
}

function showExtractionsList(records) {
  let html = '<div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Champs</th><th>Status</th></tr></thead><tbody>';
  records.forEach(record => {
    html += `
      <tr>
        <td>${frappe.format(record.extraction_date, { fieldtype: 'Datetime' })}</td>
        <td>${record.total_fields_extracted || 0} champs</td>
        <td><span class="badge badge-success">${record.status}</span></td>
      </tr>
    `;
  });
  html += '</tbody></table></div>';
  frappe.msgprint({ title: 'Extractions sauvegardées', message: html, wide: true });
}

function showAnalysesList(records) {
  let html = '<div class="table-responsive" style="max-width: 100%; overflow-x: auto;"><table class="table table-striped" style="min-width: 800px;"><thead><tr><th style="min-width: 200px;">Document</th><th style="min-width: 150px;">Type</th><th style="min-width: 180px;">Date</th><th style="min-width: 120px;">Actions</th></tr></thead><tbody>';
  records.forEach(record => {
    html += `
      <tr>
        <td>${record.document_name || 'Sans nom'}</td>
        <td>${record.document_type || 'Document'}</td>
        <td>${frappe.format(record.creation, { fieldtype: 'Datetime' })}</td>
        <td>
          <button class="btn btn-sm btn-primary" onclick="openAnalysisDoc('${record.name}')" style="white-space: nowrap;">Ouvrir</button>
        </td>
      </tr>
    `;
  });
  html += '</tbody></table></div>';
  frappe.msgprint({
    title: 'Analyses sauvegardées (' + records.length + ')',
    message: html,
    wide: true,
    size: 'extra-large'
  });
}

function openAnalysisDoc(docName) {
  $('.modal').modal('hide');
  setTimeout(function () {
    try {
      frappe.set_route('Form', 'Document Analysis', docName);
    } catch (e) {
      window.open(`/app/document-analysis/${docName}`, '_blank');
    }
  }, 500);
}

function displayGroupedResults(payload) {
  // === 1) MODE CIBLÉ (Doctype choisi) : un seul tableau, pas d’onglets ===
  if (payload.mode === 'targeted' || payload.target_doctype) {
    // Nom virtuel du "fichier" courant pour la sauvegarde
    window.currentFilename = 'Extraction ciblée';

    // Affiche directement la table unique (tu peux passer {readonly:true} si ta
    // displayUniversalResults supporte ce flag pour masquer les actions)
    displayUniversalResults({
      document_type: payload.document_type || 'Document',
      confidence: payload.confidence || 0.9,
      table_data: payload.table_data || []
    }, '#data-table', { readonly: true });

    $('#results-section').show();
    return; // ⬅️ très important: on sort ici → AUCUN onglet créé
  }

  // === 2) MODE LARGE (pas de Doctype) : comportement habituel avec onglets ===
  const tabs = [];
  if (payload.merged && payload.merged.table && payload.merged.table.length) {
    tabs.push({
      id: 'tab-merged',
      label: 'Fusion',
      data: payload.merged.table,
      meta: { doc_type: payload.document_type, conf: payload.confidence, filename: 'Fusion' }
    });
  }
  (payload.files || []).forEach((f, i) => {
    tabs.push({
      id: 'tab-file-' + i,
      label: f.filename,
      data: f.table,
      meta: { doc_type: f.document_type, conf: f.confidence, filename: f.filename }
    });
  });

  // barre d’onglets + conteneur du tableau
  let nav = '<ul class="nav nav-tabs" id="pdf-tabs">';
  tabs.forEach((t, i) => {
    nav += `<li class="nav-item"><a class="nav-link ${i === 0 ? 'active' : ''}" data-tab="${t.id}" href="javascript:void(0)">${t.label}</a></li>`;
  });
  nav += '</ul><div id="tab-container" style="margin-top:12px;"></div>';
  $('#data-table').html(nav);

  function show(i) {
    const t = tabs[i];
    window.currentFilename = t.meta.filename || 'PDF';
    displayUniversalResults({
      document_type: t.meta.doc_type || 'Document',
      confidence: t.meta.conf || 0.9,
      table_data: t.data || []
    }, '#tab-container');
  }

  $('#pdf-tabs .nav-link').on('click', function () {
    $('#pdf-tabs .nav-link').removeClass('active');
    $(this).addClass('active');
    const idx = $(this).parent().index();
    show(idx);
  });

  show(0);
  $('#results-section').show();
}

// ------- Création d’un document du Doctype choisi -------
$('#create-doctype-btn').click(function () {
  if (!window.currentTableData || !window.currentTableData.length) {
    frappe.msgprint('Aucune donnée à envoyer');
    return;
  }
  const targetDt = $('#target-doctype').val();
  if (!targetDt) {
    frappe.msgprint('Veuillez choisir un Doctype dans la liste (ex: CompanyCreationRequest)');
    return;
  }

  // construit {field, value} à partir de la table affichée
  const payload = [];
  $('#extraction-table tbody tr').each(function (index) {
    const row = $(this);
    payload.push({
      field: row.find('.field-name-hidden').val(), // <-- fieldname technique
      value: row.find('.field-value').val() || (window.currentTableData[index]?.value || '')
    });
  });

  frappe.call({
    method: 'company_creation.pdf_extractor.api.create_doctype_record',
    args: { target_doctype: targetDt, data: JSON.stringify(payload) },
    callback: function (r) {
      if (r.message && r.message.success) {
        frappe.msgprint('✅ Document créé: ' + r.message.name);
        frappe.set_route('Form', targetDt, r.message.name);
      } else {
        frappe.msgprint('❌ Erreur: ' + (r.message && r.message.error ? r.message.error : 'inconnue'));
      }
    }
  });
});
